#!/usr/bin/env bash
# Question 11: LoadBalancer Service. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q11_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q11_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q11_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q11_NS}" delete service web-lb --ignore-not-found >/dev/null
kubectl -n "${Q11_NS}" create deployment web --image=nginx:1.27-alpine --replicas=1 --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q11_NS}" rollout status deployment/web --timeout=180s >/dev/null
: "${Q11_NS}" "${Q11_NODEPORT}"
